sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float strength;
uniform float blur;
uniform float channel;
float edgeDistance(float2 coord) {
    float b = clamp(float(blurred.eval(coord).a), 0.0005, 0.9995);
    return blur / 3.0 * log(b / (1.0 - b)) / 1.702;
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float edge = max(1.0 - float(c.a), blur > 0.0 ? 1.0 - smoothstep(0.0, blur, edgeDistance(coord)) : 0.0);
    float3 rgb = float3(unpremul(c).rgb);
    float k = clamp(strength, 0.0, 1.0) * edge;
    float greenSpill = max(rgb.g - max(rgb.r, rgb.b), 0.0);
    float blueSpill = max(rgb.b - max(rgb.r, rgb.g), 0.0);
    bool pickGreen = channel < 0.5 ? greenSpill >= blueSpill : channel < 1.5;
    if (pickGreen) {
        float d = greenSpill * k;
        rgb += float3(0.85 * d * 0.587 / 0.299, -d, 0.15 * d * 0.587 / 0.114);
    } else {
        float d = blueSpill * k;
        rgb += float3(0.5 * d * 0.114 / 0.299, 0.5 * d * 0.114 / 0.587, -d);
    }
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
